Lemma rmrep_ctx_frame' : ltac2:(zQ "i61!h9!nd!s0!hi4!tf!hh5!hs6!jjf!jm2!lr6!o0!hj0!hjf!hm2!hp1!ihf!lp0!la!is4!ise!ml0!it9!mla!mm7!lre!jve!ls6!lsd!lqd!lj4!mn2!jub!ud!v4!mje!vb!mnf!pf&>0@1$8@1$7#k0@1$e@1$8@1$7#8>2st$h1>3st'$h1>1m~0>2m'~0>0@4$h0?5HCEIL?4HSEC^4^2>0@3$hc@3$h8@2$9$0$0@4$hb$0$0$f@2$i5$f+jq0@1$ha@2$9$0$0^3^2>0@3$hd$hf^4^3>0@3$3@4$6$1$2$5$i3@1$h5^6@1$h5^7>0@3$3@4$6$a@4$d$1$2$0$4@6$c$1$2$5$0$4$b$i2@1$h4^7@1$h4^8>0@3$3@4$6$a@4$d$1$2$0$4@6$c$1$2$5$0$4$b$i0@1$h2^8@1$h2^9>0@3$3@4$6$a@4$d$1$2$0$4@6$c$1$2$5$0$4$b$i1@1$h3^9@1$h3^a>0@3$3@4$6$1$2$5$i4@1$h7^a@1$h7^b>0@3$3@1$h9@2$9$0$0@1$h6^b@1$h6^c>0@2$he^c^a@4$h0?5HCEIL?4HSEC^d^b").
Proof.
  intros st st' m m' REP MU WM ER EM EA EG ES ERs CX'.
  destruct REP as (WF & CX & GL & AR & GR & SH).
  pose proof WF as WF0.
  destruct WF as (Hres & WR & DJ & WA & WG).
  assert (Hconc : forall q, conc st' q = conc st q)
    by (intros q; unfold conc, get_region; rewrite ER; reflexivity).
  assert (Hoc : forall p, oconc st' p = oconc st p)
    by (intros p; unfold oconc, conc, get_region; rewrite ER; reflexivity).
  assert (Hpw : forall p, pw st' p = pw st p) by (intros p; unfold pw; rewrite Hoc; reflexivity).
  assert (Hmc : forall mr, meta_cells st' mr = meta_cells st mr)
    by (intros mr; unfold meta_cells; rewrite !Hpw; reflexivity).
  assert (Hgm : forall q, get_meta_rec st' q = get_meta_rec st q)
    by (intros q; unfold get_meta_rec; rewrite EM; reflexivity).
  assert (Hsh : forall rid, get_shadow st' rid = get_shadow st rid)
    by (intros rid; unfold get_shadow; rewrite ES; reflexivity).
  (* A range inside a region is disjoint from the malloc context: regions avoid the reserved bands, and the
     context lies in the band of the last image segment. *)
  assert (RD : forall rid r A n, s_regions st !! rid = Some r -> r_base r <= A -> 0 <= n ->
                 A + n <= r_base r + round_up_pg (r_len r) -> disjoint_from [(RCTX, RCTX + 928)] A n).
  { intros rid r A n Hr H1 Hn H2. destruct (WR rid r Hr) as (_ & _ & _ & _ & RF).
    destruct (rreserved_disjoint _ _ RF) as (_ & _ & _ & D4).
    cbn [disjoint_from]. split; [| exact I]. unfold RCTX. lia. }
  unfold rmrep. split; [| split; [exact CX' | split; [| split; [| split]]]].
  - unfold rregions_wf in *. rewrite ERs, ER, EA, EG. exact WF0.
  - unfold rmrep_globals in *. destruct GL as (G1 & G2 & G3 & G4 & G5 & G6).
    split; [| split; [| split; [| split; [| split]]]];
      (eapply rw_cells_transport; [eassumption | exact MU | exact WM |];
       cbn [disjoint_from]; split; [| exact I];
       unfold RCTX, RMLOCK, RNEED_LOCKS, RPAGE_SIZE, RGOT_SSP, RSSP_GUARD; simpl; lia).
  - unfold rmrep_areas in *. intros a ar Ha. rewrite EA in Ha.
    destruct (AR a ar Ha) as (A1 & A2 & A3).
    destruct (WA a ar Ha) as (r & Hr & S0 & S1 & SAL & NK & LR).
    assert (Ca : conc st a = r_base r + a.2) by (unfold conc, get_region; rewrite Hr; reflexivity).
    unfold rarea_rep. rewrite !Hconc, !Hpw.
    split; [| split].
    + eapply rw_cells_transport; [exact A1 | exact MU | exact WM |].
      eapply (RD a.1 r); [exact Hr | | |]; simpl; lia.
    + intros k Hk. rewrite Hgm, Hmc.
      eapply rw_cells_transport; [exact (A2 k Hk) | exact MU | exact WM |].
      unfold AREA_HDR, META_SIZE, NSLOTS in *.
      eapply (RD a.1 r); [exact Hr | | |]; unfold meta_cells; simpl; lia.
    + eapply rw_cells_transport; [exact A3 | exact MU | exact WM |].
      eapply (RD a.1 r); [exact Hr | | |]; simpl; lia.
  - unfold rmrep_groups in *. intros b gh Hg. rewrite EG in Hg.
    destruct (GR b gh Hg) as (w8 & Hc & Hl).
    destruct (WG b gh Hg) as (r & Hr & K & B0 & B1 & B2).
    assert (Cb : conc st b = r_base r + b.2) by (unfold conc, get_region; rewrite Hr; reflexivity).
    unfold rgroup_rep. exists w8. split; [| exact Hl].
    rewrite Hconc, Hpw.
    eapply rw_cells_transport; [exact Hc | exact MU | exact WM |].
    eapply (RD b.1 r); [exact Hr | | |]; simpl; lia.
  - unfold rmrep_shadow in *. intros rid r Hr K. rewrite ER in Hr.
    destruct (SH rid r Hr K) as (W1 & W2).
    unfold rshadow_rep. split.
    + eapply wr_at_transport; [exact W1 | exact WM].
    + intros o v Ho Hk. rewrite Hsh in Hk. destruct (W2 o v Ho Hk) as (B & V0 & V1).
      split; [| split; assumption].
      eapply bytes_at_transport; [exact B | exact MU |].
      eapply (RD rid r); [exact Hr | | |]; simpl; lia.
Qed.

